import axios from "axios";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Inventory() {
    const [inventory, setInventory] = useState([]);
    const navigate = useNavigate();

    const fetchInventory = async() => {
        try {
            const response = await axios.get(
                "http://localhost:5000/api/v1/inventory"
            )
            setInventory(response.data.data)
        } catch(error) {
            console.log(error.response?.data || error.message)
        }
    }


    const deleteInventroy = async(id) => {
        const confirmDelete = window.confirm("Are you sure delete this inventroy?")

        if(!confirmDelete) return;

        try {
            const token = localStorage.getItem("token")
            await axios.delete(
                 `http://localhost:5000/api/v1/inventory/${id}`,
            {
                headers: {
                    Autorization:  `Bearer ${token}`,
                },
            }
        )
        alert("Inventory Deleted Successfully")
        fetchInventory();
        } catch(error){
            console.log(error.response?.data || error.message)
        }
    }

    useEffect(() => {
        fetchInventory()
    }, [])

    return (
        <>
        <div className="container mt-5">
              <div className="d-flex justify-content-between mb-3">
                <h2>Inventory</h2>
                <button onClick={() => navigate("/add-inventory")} className="btn btn-inventory">Add Inventroy</button>
                </div>

                <table className="table table-bordered table-striped">
                    <thead  className="table-dark">
                        <tr>
                            <th>ID</th>
                            <th>Product ID</th>
                            <th>Stock Quantity</th>
                            <th>Warehouse</th>
                            <th>Last Update</th>
                            <th>Action</th>
                            </tr>
                        </thead>

                        <tbody>
                            {inventory.map((item) => (
                               <tr key={item.id}>
                                <td>{item.id}</td>
                                <td>{item.product_id}</td>
                                <td>{item.stock_quantity}</td>
                                <td>{item.warehouse}</td>
                                <td>{item.last_update}</td>

                                  <td>
                <button
                  className="btn btn-warning btn-sm me-2"
                  onClick={() =>
                    navigate(`/edit-inventory/${item.id}`)
                  }
                >
                  Edit
                </button>

                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => deleteInventory(item.id)}
                >
                  Delete
                </button>
              </td>
                               </tr>
                            ))}
                        </tbody>
                    </table>
            </div>
        </>
    )
}
